    <script>
      (function () {
        var S = document.getElementById("status"),
          DOT = document.getElementById("dot"),
          HIDBTN = document.getElementById("hid-btn");
        var state = 0,
          connected = false,
          gpIdx = null;
        function doSend() {
          try {
            fetch("/b" + state, { method: "POST", keepalive: true });
          } catch (e) {}
          if (!connected) {
            connected = true;
            DOT.classList.add("on");
            S.textContent = "CONNECTED";
          }
        }
        function send() {
          doSend();
        }
        function press(mask) {
          if (mask >= 254) {
            state = mask;
            send();
            state = 0;
            return;
          }
          if (!(state & mask)) {
            state |= mask;
            send();
          }
        }
        function release(mask) {
          if (mask >= 254) return;
          if (state & mask) {
            state &= ~mask;
            send();
          }
        }
        function btnOn(m) {
          document
            .querySelectorAll('[data-b="' + m + '"]')
            .forEach(function (e) {
              e.classList.add("active");
            });
        }
        function btnOff(m) {
          document
            .querySelectorAll('[data-b="' + m + '"]')
            .forEach(function (e) {
              e.classList.remove("active");
            });
        }
        function applyMask(m) {
          [1, 2, 4, 8, 16, 32, 64, 128].forEach(function (b) {
            if (m & b) btnOn(b);
            else btnOff(b);
          });
          state = m;
          send();
        }
        var touchMap = new Map();
        function processTouch(e) {
          e.preventDefault();
          var liveIds = new Set();
          for (var i = 0; i < e.touches.length; i++) {
            var t = e.touches[i];
            liveIds.add(t.identifier);
            var el = document.elementFromPoint(t.clientX, t.clientY);
            var m = el && el.dataset.b ? +el.dataset.b : null;
            var prev = touchMap.get(t.identifier);
            if (prev !== undefined && prev !== m) {
              touchMap.delete(t.identifier);
              release(prev);
              btnOff(prev);
            }
            if (m !== null && touchMap.get(t.identifier) !== m) {
              touchMap.set(t.identifier, m);
              press(m);
              btnOn(m);
            }
          }
          for (var p of touchMap) {
            if (!liveIds.has(p[0])) {
              touchMap.delete(p[0]);
              release(p[1]);
              btnOff(p[1]);
            }
          }
        }
        function processEnd(e) {
          e.preventDefault();
          var liveIds = new Set();
          for (var i = 0; i < e.touches.length; i++)
            liveIds.add(e.touches[i].identifier);
          for (var p of touchMap) {
            if (!liveIds.has(p[0])) {
              touchMap.delete(p[0]);
              release(p[1]);
              btnOff(p[1]);
            }
          }
        }
        document.addEventListener("touchstart", processTouch, {
          passive: false,
        });
        document.addEventListener("touchmove", processTouch, {
          passive: false,
        });
        document.addEventListener("touchend", processEnd, { passive: false });
        document.addEventListener("touchcancel", processEnd, {
          passive: false,
        });
        var mouseBtn = null;
        document.querySelectorAll("[data-b]").forEach(function (el) {
          el.addEventListener("mousedown", function (e) {
            e.preventDefault();
            var m = +el.dataset.b;
            mouseBtn = m;
            press(m);
            btnOn(m);
          });
        });
        window.addEventListener("mouseup", function () {
          if (mouseBtn !== null) {
            var m = mouseBtn;
            mouseBtn = null;
            release(m);
            btnOff(m);
          }
        });
        var KM = {
          ArrowUp: 16,
          w: 16,
          W: 16,
